const express = require('express');
const puppeteer = require('puppeteer');
const mongoose = require('mongoose');

const app = express();

const DashboardSchema = new mongoose.Schema({
  title: String,
  ownerId: mongoose.Schema.Types.ObjectId,
  isPublic: Boolean,
  slug: String
});
const Dashboard = mongoose.model('Dashboard', DashboardSchema);

app.get('/api/dashboards/:slug/preview-card', async (req, res) => {
  const { slug } = req.params;

  // Ensure dashboard is public or owned by authenticated user
  const dashboard = await Dashboard.findOne({ slug });
  if (!dashboard) {
    return res.status(404).json({ error: 'Dashboard not found' });
  }

  const isOwner = req.user && dashboard.ownerId.equals(req.user._id);
  if (!dashboard.isPublic && !isOwner) {
    return res.status(403).json({ error: 'Access denied to private dashboard preview' });
  }

  const browser = await puppeteer.launch({ headless: 'new' });
  const page = await browser.newPage();
  await page.setViewport({ width: 1200, height: 630 });

  await page.goto(`http://127.0.0.1:8080/internal/dashboards/${dashboard._id}?token=${process.env.INTERNAL_RENDER_TOKEN}`);
  const imageBuffer = await page.screenshot({ type: 'jpeg', quality: 80 });

  await browser.close();
  res.setHeader('Content-Type', 'image/jpeg');
  return res.send(imageBuffer);
});

module.exports = app;
